from taf.nms.netact.command import CommandBuilder


class IntegrationDataUploadError(Exception):
    pass


class IntegrationDataMixin:

    def upload_integration_data(self, dist_name, agent_hostname, mr_dn='MRC-NWI3/MR-NWI3'):
        """
        Trigger Integration Data Upload using neIntegration tools:
        (https://confluence.int.net.nokia.com/display/OSSRD/How+to+do+integration+data+upload+without+opening+Monitor)
        **NOTE** TO PERFORM INTEGRATION DATA UPLOAD, HOST WITH NWI3 SERVICE IS NEEDED!!!

        :param string dist_name: e.g. 'PLMN-PLMN/OMS-413'
        :param string agent_hostname: IP address or host name of agent e.g. '10.42.29.46'
        :param string mr_dn: FQDN of maintenance region object, use this FQDN if it exists.
        :return: integration data upload result
        :rtype: string
        """
        command = CommandBuilder(
            executable='python /opt/oss/NSN-nwi3/bin/neIntegration.zip',
            options={
                '-a': dist_name,
                '-i': agent_hostname,
                '-m': mr_dn
            }
        )
        with self.nodes.get_node('nwi3') as ssh:
            output = ssh.execute_command(command.text).stdout
        if f'Integration result : [{dist_name} : FAIL]' in str(output):
            raise IntegrationDataUploadError(output)
        return output
